                                || key.contains("TOKEN")
                                || key.contains("SECRET")
120→                            {
                                "***"
                            } else {
                                &value
                            }
                        );
                    } else {
                        skipped_count += 1;
                        debug!("Skipped (already set): {}", key);
                    }
130→                }
            }

            info!(
